targets=[]
for i,(name,assets,old) in enumerate([('log1p_bank','exports/p3a_feature_sensitivity_v1/log1p_previous','results/p3a_log1p_optimized_v1'),('synthetic_N2000','results/p3b_n_scaling_v1/N2000/target','results/p3b_n_scaling_v1/N2000/optimized'),('synthetic_N128000','results/p3b_n_scaling_v1/N128000/target','results/p3b_n_scaling_v1/N128000/optimized')]):
 targets.append(dict(id=name,assets=assets,parent_candidates=old+'/FROZEN_CANDIDATES.json',parent_protocol=old+'/PROTOCOL.json',pilot_seeds=[410100+1000*i,410101+1000*i],validation_seeds=list(range(410200+1000*i,410208+1000*i))))
c=dict(name='P5 focused ULA baseline and initialization sensitivity extension v1',frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),classification='New prospective protocol amendment motivated by seen P1-P4/review; not retroactive confirmation of original experiments',backend='JAX CPU float64; rerun all compared candidates in same session/environment',targets=targets,ula=dict(step_coefficients=[.025,.05,.1,.2,.4,.8,1.6],h_rule='coefficient/actual LP; no outcome-dependent extra search',pilot_replicas=64,pilot_horizon=2048,pilot_checkpoints=[128,256,384,512,1024,2048],max_frozen_candidates=4,selection='Only settings stable and complete for both pilot seeds. Rank checkpoint points by four-dimensional nondomination of warm,cold,SW2,relative variance. Select step settings by most rank0 points, smallest minimum rank, greatest inverse-rank coverage, then smaller h. No threshold-specific tuning.',minibatch='full data; no irrelevant batch-size sweep',implementation='Exact full-data logistic gradient; benchmark memory-bounded data-block GEMM variants using non-inference streams, freeze fastest median of3 gradient calls before pilot. No subsampling.'),comparators='All CV1/CV2 candidates in each ORIGINAL pilot-frozen FROZEN_CANDIDATES.json, including previously failed candidates. No retuning and no post-hoc survivor selection from old validation.',validation=dict(replicas=512,horizon=4096,checkpoints=[128,256,384,512,1024,2048,4096],initialization='independent mode-start replicas; paired Gaussian streams and same seeds across methods',failure='Any failed replica, missing seed or incomplete run excludes complete configuration at all checkpoints; retain failed/censored records'),metrics=dict(sw2='same approved target-specific whitening,projections and two reference clouds',variance='relative coordinate variance NRMSE from per-replica ergodic sums over steps1..K; no discarded burn-in, intentionally finite-horizon from-mode error',threshold_sw2=.3,variance_thresholds=[round(.2+.01*i,2) for i in range(41)]),cost='Warm=stored mode-fit attribution+current actual estimator/metric/state preparation+synchronized sampler/RNG; cold adds measured shape-specific compile. JIT warmup, implementation benchmark, reference, functionals, scoring, storage separate. Compilation cache is declared, not fresh-process cold.',bootstrap=dict(draws=10000,seed=419900,unit='paired whole seeds; reselect minima each draw; preserve Not-Reached mass; simultaneous maxabs band across all3 methods,eligible candidates,checkpoints,refs,metrics; conditional on fixed references'),budgets=dict(total_research_seconds=21600,target_research_seconds=7200,per_run_sampler_seconds=600,rule='Record budget censoring, never call a censored ULA slower or NotReached-on-accuracy. No unbounded search.'),li_diagnostic=dict(target='gpu_replication/german_target.npz',h=1.3203191532898161e-5,alpha=.99,epsilon=1e-5,batch=32,replicas=64,iterations=2048,seeds=[410030,410031],pilot_seed=410001,pilot_batches=32,methods=['sgld','cv1','cv2'],initializations=['zero','independent_anchor_pilot'],purpose='Matched initialization sensitivity, not an optimized adaptive frontier or exact replay of old NumPy RNG. Same minibatch/noise streams and all other settings within seed. Do not relabel an initialization variant as a bug fix.'),implementation_checks='float64 full gradient,constant metric/noise factor and fixed-input update against independent NumPy; blocked vs dense exact-gradient equivalence; CV kernels reused unchanged',original_results='Never overwritten; all new outputs in results/exports p5_baseline_extension_v1; no proof edits',source_hashes={})
for t in targets:
 for rel in [t['parent_candidates'],t['parent_protocol']]+[t['assets']+'/'+n for n in ['target.npz','scoring.npz','metadata.json','reference_pair.json','reference_0.json','reference_1.json']]:c['source_hashes'][rel]=sha(R/rel)
for rel in ['gpu_replication/german_target.npz','gpu_replication/batched_sampler.py','p2_screening/kernels.py','src/sgld_cv/preconditioners.py']:c['source_hashes'][rel]=sha(R/rel)
newseeds={s for t in targets for s in t['pilot_seeds']+t['validation_seeds']}|set(c['li_diagnostic']['seeds'])|{410001,410010};used=set()
for folder in ['results','exports']:
 for p in (R/folder).rglob('*summary.json'):
  if 'p5_baseline_extension_v1' in str(p):continue
